package net.civeira.phylax.feature.access.userloginthrottle.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.userloginthrottle.domain.UserLoginThrottle;
import net.civeira.phylax.feature.access.userloginthrottle.domain.valueobject.FailedLoginAttemptsVO;

class FailedLoginAttemptsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of failed login attempts of user login throttle")
  void test_failed_login_attempts_value_holder_assign_plain_value() {
    Object holder = new Object();
    FailedLoginAttemptsValueHolder<Object> value = new FailedLoginAttemptsValueHolder<>(holder);
    Assertions.assertSame(holder, value.failedLoginAttempts(1), "Setters must return the holder");
    Assertions.assertTrue(value.getFailedLoginAttemptsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getFailedLoginAttempts().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.failedLoginAttemptsNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getFailedLoginAttemptsValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getFailedLoginAttempts().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of failed login attempts of user login throttle")
  void test_failed_login_attempts_value_holder_assign_value_object() {
    Object holder = new Object();
    FailedLoginAttemptsValueHolder<Object> value = new FailedLoginAttemptsValueHolder<>(holder);
    FailedLoginAttemptsVO vo = FailedLoginAttemptsVO.from(1);
    Assertions.assertFalse(value.getFailedLoginAttemptsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.failedLoginAttempts(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getFailedLoginAttemptsValue().orElseThrow());
    Assertions.assertSame(holder, value.failedLoginAttempts(Optional.empty()));
    Assertions.assertFalse(value.getFailedLoginAttemptsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.failedLoginAttempts(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFailedLoginAttemptsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of failed login attempts of user login throttle against the original")
  void test_failed_login_attempts_value_holder_read() {
    Object holder = new Object();
    FailedLoginAttemptsValueHolder<Object> value = new FailedLoginAttemptsValueHolder<>(holder);
    FailedLoginAttemptsVO vo = FailedLoginAttemptsVO.from(1);
    FailedLoginAttemptsVO other = FailedLoginAttemptsVO.from(1);
    UserLoginThrottle original = Mockito.mock(UserLoginThrottle.class);
    Mockito.when(original.getFailedLoginAttemptsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readFailedLoginAttempts(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFailedLoginAttempts(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.failedLoginAttempts(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readFailedLoginAttempts(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readFailedLoginAttempts(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of failed login attempts of user login throttle")
  void test_failed_login_attempts_value_holder_unset() {
    Object holder = new Object();
    FailedLoginAttemptsValueHolder<Object> value = new FailedLoginAttemptsValueHolder<>(holder);
    FailedLoginAttemptsVO vo = FailedLoginAttemptsVO.from(1);
    value.failedLoginAttempts(vo);
    Assertions.assertSame(holder,
        value.unsetFailedLoginAttemptsIfMatches("failedLoginAttempts_other"));
    Assertions.assertTrue(value.getFailedLoginAttemptsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetFailedLoginAttemptsIfMatches("failedLoginAttempts"));
    Assertions.assertFalse(value.getFailedLoginAttemptsValue().isPresent(),
        "The field name must clear the value");
    value.failedLoginAttempts(vo);
    Assertions.assertSame(holder, value.unsetFailedLoginAttempts());
    Assertions.assertFalse(value.getFailedLoginAttemptsValue().isPresent(),
        "Unset must clear the value");
  }
}
